'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const W=410,H=650,LINE=122;
const names=['蹲蹲奶龙','圆肚奶龙','长颈奶龙','霸王奶龙','剑背奶龙','三角奶龙','龟甲奶龙','爬爬奶龙','大嘴奶龙'];
const radii=[23,30,38,47,57,69,82,97,114];
const colors=['#fff0a4','#ffdf65','#d9d9fd','#ffd5df','#c5eaf4','#d3e9ba','#ffc5a5','#cee0f8','#ffcf44'];
const sprites=names.map(()=>new Image());
let assetsReady=false;
let balls=[],effects=[],score=0,current=0,next=pick(),aim=240,paused=false,over=false,lastDrop=-999,clock=0,danger=0,unlocked=0,pendingRestart=false;
// The next piece is intentionally hidden and drawn from five levels. Small pieces
// are common, while occasional larger pieces make planning and stacking harder.
function pick(){const roll=Math.random();return roll<.42?0:roll<.72?1:roll<.9?2:roll<.98?3:4}
function dragon(c,level,x,y,r,alpha=1){const img=sprites[level];c.save();c.globalAlpha=alpha;if(img.complete&&img.naturalWidth){const f=img.frame||[0,0,img.naturalWidth,img.naturalHeight],scale=2*r/Math.max(f[2],f[3]),w=f[2]*scale,h=f[3]*scale;c.drawImage(img,...f,x-w/2,y-h/2,w,h)}c.restore()}
function characterFrame(img){const buffer=document.createElement('canvas');buffer.width=img.naturalWidth;buffer.height=img.naturalHeight;const c=buffer.getContext('2d',{willReadFrequently:true});c.drawImage(img,0,0);try{const {data}=c.getImageData(0,0,buffer.width,buffer.height);let left=buffer.width,top=buffer.height,right=0,bottom=0;for(let y=0;y<buffer.height;y++)for(let x=0;x<buffer.width;x++){if(data[(y*buffer.width+x)*4+3]>48){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y)}}if(right>=left&&bottom>=top)return [left,top,right-left+1,bottom-top+1]}catch{}return [0,0,img.naturalWidth,img.naturalHeight]}
function updateUI(){document.getElementById('score').textContent=score;const n=document.getElementById('next'),c=n.getContext('2d');c.clearRect(0,0,160,160);dragon(c,next,80,80,59);document.getElementById('nextName').textContent=names[next]}
names.forEach((name,i)=>{const el=document.createElement('div');el.className='level';el.innerHTML='<canvas width="120" height="120"></canvas><span>'+(i+1)+' · '+name.replace('奶龙','')+'</span>';el.title=(i+1)+'级 · '+name+' · 原图 '+(i+1)+'.jpg';document.getElementById('levels').append(el)});
sprites.forEach((img,i)=>{img.onload=()=>{img.frame=characterFrame(img);const c=document.querySelectorAll('.level canvas')[i];if(c){const cc=c.getContext('2d');cc.clearRect(0,0,120,120);dragon(cc,i,60,60,54)}assetsReady=sprites.every(s=>s.complete&&s.naturalWidth);if(assetsReady)document.getElementById('status').textContent='随机投放已开启，注意大只奶龙！';updateUI()};img.onerror=()=>{document.getElementById('status').textContent='角色图片加载失败，请刷新重试'};img.src='models/'+(i+1)+'.png'});
function drop(){if(paused||over||clock-lastDrop<0.7||!assetsReady)return false;let r=radii[current];balls.push({x:Math.max(r+7,Math.min(W-r-7,aim)),y:64,r,level:current,vx:0,vy:0,born:clock});lastDrop=clock;current=next;next=pick();updateUI();document.getElementById('status').textContent='碰在一起，就能变大！';return true}
function showOverlay(title,text,label){document.getElementById('overlay').hidden=false;document.getElementById('overlayTitle').textContent=title;document.getElementById('overlayText').textContent=text;document.getElementById('resume').textContent=label;document.getElementById('overline').textContent=over?'下次一定更大只':pendingRestart?'再来一局？':'休息一下'}
function pause(){if(over)return;paused=!paused;pendingRestart=false;document.getElementById('overlay').hidden=!paused;document.getElementById('pause').textContent=paused?'继续':'暂停';if(paused)showOverlay('已暂停','奶龙在等你回来。','继续游戏')}
function reset(){balls=[];effects=[];score=0;current=0;next=pick();danger=0;paused=false;over=false;pendingRestart=false;clock=0;lastDrop=-999;unlocked=0;document.getElementById('overlay').hidden=true;document.getElementById('pause').textContent='暂停';document.getElementById('status').textContent='随机投放已开启，注意大只奶龙！';updateUI()}
document.getElementById('pause').onclick=pause;
document.getElementById('restart').onclick=()=>{if(!balls.length||over){reset();return}paused=true;pendingRestart=true;showOverlay('重新开始？','本局得分将清零。','继续本局')};
document.getElementById('restartOverlay').onclick=reset;
document.getElementById('resume').onclick=()=>{if(over)reset();else{paused=false;pendingRestart=false;document.getElementById('overlay').hidden=true;document.getElementById('pause').textContent='暂停'}};
function point(e){const b=canvas.getBoundingClientRect();aim=Math.max(radii[current]+7,Math.min(W-radii[current]-7,(e.clientX-b.left)*W/b.width))}
canvas.addEventListener('pointerdown',e=>{point(e);canvas.setPointerCapture(e.pointerId);canvas.focus({preventScroll:true})});canvas.addEventListener('pointermove',point);canvas.addEventListener('pointerup',e=>{point(e);drop()});
window.addEventListener('keydown',e=>{if(e.target.tagName==='BUTTON')return;if(['ArrowLeft','ArrowRight',' ','p','P'].includes(e.key)){e.preventDefault();if(e.key.toLowerCase()==='p')pause();else if(e.key===' ')drop();else if(!paused&&!over)aim=Math.max(radii[current]+7,Math.min(W-radii[current]-7,aim+(e.key==='ArrowLeft'?-18:18)))}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&!paused&&!over&&balls.length)pause()});
function step(dt){clock+=dt;for(const b of balls){b.vy+=1050*dt;b.vx*=0.997;b.vy*=0.999;b.x+=b.vx*dt;b.y+=b.vy*dt}
for(let iter=0;iter<7;iter++){for(const b of balls){if(b.x<b.r+6){b.x=b.r+6;b.vx=Math.abs(b.vx)*.18}if(b.x>W-b.r-6){b.x=W-b.r-6;b.vx=-Math.abs(b.vx)*.18}if(b.y>H-b.r-9){b.y=H-b.r-9;b.vy=-Math.abs(b.vy)*.08;b.vx*=.94}}
for(let i=0;i<balls.length;i++){for(let j=i+1;j<balls.length;j++){const a=balls[i],b=balls[j];let dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy),sum=a.r+b.r;if(d>sum+.2)continue;if(a.level===b.level&&a.level<8){const level=a.level+1;const n={x:(a.x+b.x)/2,y:(a.y+b.y)/2,r:radii[level],level,vx:(a.vx+b.vx)/2,vy:Math.min(0,(a.vy+b.vy)/2),born:clock};balls.splice(j,1);balls.splice(i,1,n);score+=2**level*5;effects.push({x:n.x,y:n.y,r:n.r,t:0,text:'+'+(2**level*10)});if(level>unlocked){unlocked=level;document.getElementById('status').textContent=level===8?'合成 9 级大奶龙啦！继续挑战高分':'新朋友：'+names[level]+'！'}updateUI();break}d=Math.max(d,.01);let nx=dx/d,ny=dy/d;if(!dx&&!dy){nx=1;ny=0}const ma=a.r*a.r,mb=b.r*b.r,total=ma+mb,pen=Math.max(0,sum-d);a.x-=nx*pen*mb/total;a.y-=ny*pen*mb/total;b.x+=nx*pen*ma/total;b.y+=ny*pen*ma/total;const rel=(b.vx-a.vx)*nx+(b.vy-a.vy)*ny;if(rel<0){const impulse=-(1.05)*rel/(1/ma+1/mb);a.vx-=impulse*nx/ma;a.vy-=impulse*ny/ma;b.vx+=impulse*nx/mb;b.vy+=impulse*ny/mb}}}}
const high=balls.some(b=>clock-b.born>1.6&&b.y-b.r<LINE);danger=high?danger+dt:0;if(danger>=2.2){over=true;showOverlay('奶龙装满啦！','本局获得 '+score+' 分，最高合成'+names[unlocked]+'。','再玩一次');document.getElementById('status').textContent='挑战结束 · 得分 '+score}effects.forEach(e=>e.t+=dt);effects=effects.filter(e=>e.t<.8)}
function render(){ctx.clearRect(0,0,W,H);ctx.fillStyle='#fff9e7';ctx.fillRect(0,0,W,H);ctx.fillStyle='#eadfb94a';for(let x=16;x<W;x+=24)for(let y=16;y<H;y+=24){ctx.beginPath();ctx.arc(x,y,1,0,7);ctx.fill()}ctx.save();ctx.setLineDash([6,7]);ctx.strokeStyle=danger?'#eb6e50':'#d7b77a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(14,LINE);ctx.lineTo(W-14,LINE);ctx.stroke();ctx.restore();ctx.font='12px Arial';ctx.fillStyle=danger?'#d2593a':'#b59f73';ctx.textAlign='left';ctx.fillText(danger?'快满了！ '+Math.max(0,3-danger).toFixed(1)+'s':'不要超过这条线哦',17,LINE+20);
if(!over){let r=radii[current],x=Math.max(r+7,Math.min(W-r-7,aim));ctx.save();ctx.setLineDash([3,8]);ctx.strokeStyle='#7d9a7550';ctx.beginPath();ctx.moveTo(x,85);ctx.lineTo(x,H-14);ctx.stroke();ctx.restore();dragon(ctx,current,x,61,r,clock-lastDrop<.55?.3:.85)}for(const b of balls)dragon(ctx,b.level,b.x,b.y,b.r);for(const e of effects){ctx.save();ctx.globalAlpha=1-e.t/.8;ctx.strokeStyle='#edb72d';ctx.lineWidth=3;ctx.beginPath();ctx.arc(e.x,e.y,e.r+e.t*40,0,Math.PI*2);ctx.stroke();ctx.font='bold 24px Arial';ctx.textAlign='center';ctx.fillStyle='#d77c18';ctx.fillText(e.text,e.x,e.y-e.r-e.t*50);ctx.restore()}}
let prev=0,acc=0;function frame(t){if(!prev)prev=t;const elapsed=Math.min((t-prev)/1000,.06);prev=t;if(!paused&&!over){acc+=elapsed;while(acc>=1/120){step(1/120);acc-=1/120;if(over)break}}else acc=0;render();requestAnimationFrame(frame)}requestAnimationFrame(frame);updateUI();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_merge_game',description:'Read score, pause state and dragon levels in the current merge game.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({score,paused,over,highestLevel:unlocked+1,dragons:balls.length})})).catch(()=>{})}catch{}}
